"""Public project terms, version 2026-10-31-v1. Written scope and mandatory rights prevail."""
from html import escape as E
VERSION='2026-10-31-v1'
CLAUSES=[
(('Confirmation & project start','项目确认与开工','Pengesahan & permulaan'),
('An enquiry is not a confirmed project. Work starts after both parties confirm the written scope, price, deliverables and schedule, and the 50% deposit is verified. Email or an explicitly agreed written message can record confirmation. Later policy changes do not rewrite an existing agreement.','咨询不等于确认项目。双方书面确认范围、价格、交付内容和排期，并核实收到 50% 订金后开工；可通过邮件或双方明确认可的书面消息确认。后续政策更新不追溯变更已确认项目。','Pertanyaan bukan projek disahkan. Kerja bermula selepas kedua-dua pihak mengesahkan skop, harga, hasil dan jadual secara bertulis serta deposit 50% diterima. E-mel atau mesej bertulis yang dipersetujui boleh merekodkan pengesahan. Perubahan polisi kemudian tidak mengubah perjanjian sedia ada.')),
(('50% / 30% / 20% payments','50%／30%／20% 分期付款','Bayaran 50% / 30% / 20%'),
('50% starts the project; 30% is due after written approval of the development preview; the final 20% follows acceptance and is due before public launch or final handover. Only released, agreed milestones are payable. Uploading a receipt does not prove funds received. Invoices and verified-payment receipts are separate.','50% 用于启动项目；开发预览书面确认后支付 30%；验收后、正式上线或最终交付前支付 20%。只收取已确认并开放阶段的款项。上传凭证不代表到账，付款账单与核实到账后的收据分开提供。','50% memulakan projek; 30% selepas kelulusan pratonton pembangunan secara bertulis; baki 20% selepas penerimaan dan sebelum pelancaran atau serahan akhir. Hanya pencapaian dipersetujui yang dibuka perlu dibayar. Resit dimuat naik tidak membuktikan dana diterima. Invois dan resit bayaran disahkan adalah berasingan.')),
(('Cancellation & the 50% deposit','中途取消与 50% 订金','Pembatalan & deposit 50%'),
('Once confirmed work has started, client cancellation does not create an automatic refund entitlement: the 50% deposit is normally non-refundable for reasonable work performed, reserved capacity and approved non-recoverable commitments. Retention must be proportionate to reasonable compensation and applicable law; any amount that must be refunded or exceeds a reasonable settlement is returned. Cancellation must be requested in writing; further unapproved work is not charged.','双方确认并开始搭建后，不接受无成本的单方取消；客户中途取消时，50% 订金原则不退，用于合理已完成工作、排期投入及已获同意且不可退的费用。实际保留金额须与合理补偿相称并符合适用法律，依法应退或超出合理结算的部分退还。取消须书面提出，不继续收取未经同意的新工作费用。','Selepas kerja disahkan bermula, pembatalan pelanggan tidak memberi hak bayaran balik automatik: deposit 50% lazimnya tidak dipulangkan bagi kerja munasabah, kapasiti ditempah dan komitmen diluluskan yang tidak boleh dipulangkan. Amaun ditahan mesti seimbang dengan pampasan munasabah dan undang-undang; lebihan penyelesaian munasabah atau amaun yang wajib dipulangkan akan dikembalikan. Pembatalan diminta bertulis; kerja lanjut tanpa persetujuan tidak dicaj.')),
(('Before-start cancellation & supplier default','开工前取消与我方未履约','Pembatalan sebelum mula & kegagalan pembekal'),
('Before work starts, unused advance payments are returned after any previously approved, non-recoverable third-party costs are itemised. If either party materially breaches the agreement, the other gives written notice and a reasonable opportunity to remedy it. If Kenny Studio cannot deliver the agreed work, the unearned balance is refunded and paid, usable work is handed over as agreed. This policy does not remove statutory refund or remedy rights.','尚未开工时取消，预付款扣除先前已同意且不可退的第三方费用后，未使用部分退还并提供明细。任何一方严重违约，另一方应书面通知并给予合理补救机会。若 Kenny Studio 无法履行约定工作，退还未履行部分款项，并按约定交接已付款且可使用的成果；不排除依法享有的退款和救济权利。','Jika dibatalkan sebelum kerja bermula, pendahuluan tidak digunakan dipulangkan selepas kos pihak ketiga yang diluluskan dan tidak boleh dipulangkan diperincikan. Pelanggaran material memerlukan notis bertulis dan peluang munasabah untuk diperbetulkan. Jika Kenny Studio tidak dapat menyiapkan kerja, baki belum diperoleh dipulangkan dan hasil berguna yang telah dibayar diserahkan seperti dipersetujui. Hak remedi berkanun kekal.')),
(('Revisions & extra scope','修改次数与新增范围','Pindaan & skop tambahan'),
('The published website packages include two consolidated revision rounds within the approved direction, unless the written quote states otherwise. One round is one collected feedback list. Extra pages, functions or a new design direction need an agreed quotation before work. Defects in agreed work are corrected without using a revision round. No extra work is charged without approval.','除书面报价另有约定，网站套餐含已确认方向内 2 轮集中修改，每轮为一次汇总反馈。新增页面、功能或推翻原设计方向，先报价确认再制作。约定成果的缺陷修复不占修改轮次；未经客户同意不收取额外工作费用。','Pakej laman merangkumi dua pusingan pindaan terkumpul dalam arah diluluskan, kecuali sebut harga menyatakan sebaliknya. Satu pusingan ialah satu senarai maklum balas. Halaman, fungsi atau arah reka baharu memerlukan sebut harga dipersetujui dahulu. Pembaikan kecacatan tidak menggunakan pusingan pindaan. Tiada caj kerja tambahan tanpa kelulusan.')),
(('Content, access & responsibilities','素材、权限与双方责任','Kandungan, akses & tanggungjawab'),
('The client supplies accurate, authorised copy, logos, media and necessary account access, and confirms business/legal claims. Kenny Studio uses reasonable care, works within the agreed scope and protects access credentials. Neither party may provide material or instructions that infringe others\' rights. Technical access is limited to what is needed.','客户提供准确、获授权的文字、Logo、媒体与必要账号权限，并确认业务和合规声明。Kenny Studio 按约定范围合理谨慎制作并妥善保护权限；双方不得提供侵犯他人权利的内容或指示，只使用完成项目所需的权限。','Pelanggan membekalkan teks, logo, media dan akses yang tepat serta dibenarkan, dan mengesahkan dakwaan perniagaan/undang-undang. Kenny Studio bekerja dengan penjagaan munasabah mengikut skop dan melindungi kelayakan akses. Kedua-dua pihak tidak boleh melanggar hak pihak lain. Akses dihadkan kepada keperluan projek.')),
(('Schedule, delays & pauses','工期、延期与暂停','Jadual, kelewatan & penangguhan'),
('Dates depend on deposit receipt, content readiness and timely feedback. Client delays shift the schedule; Kenny Studio will communicate its own delays and propose an updated date. After 14 calendar days without required client input, a written reminder may be followed by a pause and mutually agreed rescheduling. Silence is not acceptance and does not automatically forfeit payments.','工期取决于订金到账、素材齐备和及时反馈。客户延迟会顺延排期；我方延迟也须沟通原因及新日期。所需资料或反馈超过 14 个自然日未收到，可书面提醒后暂停，并协商恢复排期。沉默不视为验收，也不自动没收款项。','Tarikh bergantung pada deposit, kandungan dan maklum balas tepat masa. Kelewatan pelanggan mengalihkan jadual; kelewatan Kenny Studio juga dimaklumkan bersama tarikh baharu. Selepas 14 hari kalendar tanpa input diperlukan, peringatan bertulis boleh diikuti penangguhan dan penjadualan semula bersama. Diam bukan penerimaan dan tidak melucutkan bayaran secara automatik.')),
(('Review, acceptance & defect support','验收与缺陷支持','Semakan, penerimaan & sokongan kecacatan'),
('The client receives a testable preview and an agreed deliverables checklist. Please provide consolidated acceptance feedback within seven working days or agree more review time. Acceptance is recorded explicitly in writing; silence is not approval. Agreed build defects reported within 30 days of handover are corrected without extra development fees; new features and third-party changes are separate.','提供可测试预览及约定交付清单。请在 7 个工作日内汇总验收反馈，或协商延长；验收以明确书面确认为准，不因沉默自动通过。交付后 30 天内提出的约定制作缺陷免费修复；新增功能及第三方变更另计。','Pratonton boleh diuji dan senarai hasil dipersetujui disediakan. Beri maklum balas terkumpul dalam tujuh hari bekerja atau persetujui masa tambahan. Penerimaan direkod bertulis; diam bukan kelulusan. Kecacatan binaan dipersetujui yang dilapor dalam 30 hari selepas serahan dibaiki tanpa fi pembangunan tambahan; fungsi baharu dan perubahan pihak ketiga berasingan.')),
(('Ownership, handover & portfolio use','版权、交付与作品展示','Pemilikan, serahan & portfolio'),
('After full payment, the client receives the bespoke final deliverables and account access stated in the quotation. Reusable tools, pre-existing templates and third-party code/media remain under their respective ownership or licences. Unselected concepts are excluded unless agreed. Domains belong to the client. Public portfolio display of client work requires their written permission.','付清款项后，交付报价列明的定制最终成果及账号权限。可复用工具、既有模板、第三方代码和素材按各自版权或许可证使用；未选用方案不默认交付。域名归客户所有，公开展示客户项目须取得客户书面同意。','Selepas bayaran penuh, pelanggan menerima hasil akhir tersuai dan akses akaun dalam sebut harga. Alat boleh guna semula, templat sedia ada dan kod/media pihak ketiga kekal di bawah pemilikan atau lesen masing-masing. Konsep tidak dipilih tidak termasuk kecuali dipersetujui. Domain milik pelanggan. Paparan portfolio memerlukan izin bertulis pelanggan.')),
(('Domain, hosting, renewals & care','域名、托管、续费与维护','Domain, hosting, pembaharuan & penjagaan'),
('Website packages include one standard domain for year one, with suffix and registration budget confirmed in writing; premium-domain extras are separate. Static showcase packages include first-year basic static hosting, then RM150–300/year. Sites needing a server, orders, e-commerce or server CMS are quoted from RM60–100/month from year one; platform subscriptions are separate. Domain renewal is provider cost plus RM30–50/year if managed by Kenny Studio; self-renewal has no management charge. Care starts at RM150/month separately. Renewal needs written agreement, not automatic renewal consent.','网站套餐含 1 个普通域名首年，后缀及注册预算书面确认，特别域名差额另付。展示型静态套餐含首年基础静态托管，次年 RM150–300／年；需要服务器、订单、电商或服务器 CMS，第一年起 RM60–100／月起，平台订阅另列。域名代续费按平台实际费用＋RM30–50／年管理费，客户自行续费不收管理费。维护 RM150／月起另计；续费须书面确认，不默认授权自动扣费。','Pakej laman termasuk satu domain standard tahun pertama dengan akhiran dan bajet bertulis; domain premium tambahan berasingan. Pakej pameran statik termasuk hosting asas tahun pertama, kemudian RM150–300/tahun. Pelayan, pesanan, e-dagang atau CMS berpelayan bermula RM60–100/bulan dari tahun pertama; langganan platform berasingan. Pembaharuan domain diurus pada kos penyedia + RM30–50/tahun; pembaharuan sendiri tanpa fi pengurusan. Care bermula RM150/bulan berasingan. Pembaharuan perlu persetujuan bertulis, bukan persetujuan caj automatik.')),
(('Privacy, third parties & results','保密、第三方与效果说明','Privasi, pihak ketiga & hasil'),
('Project and customer information is used for quotations, delivery, payment verification and support, with access limited to necessary providers and people. Neither party sells or discloses confidential project information without a valid basis. Third-party approvals, outages, search rankings and business revenue are not guaranteed. Kenny Studio remains responsible for its agreed work and reasonable assistance; mandatory rights are not excluded.','项目与客户信息用于报价、制作、核款和支持，仅向必要的人员或平台提供。双方无正当依据不出售或披露保密资料。第三方审批、平台故障、搜索排名及营业收入不保证；Kenny Studio 仍对自身约定工作和合理协助负责，不排除法定权利。','Maklumat digunakan untuk sebut harga, serahan, pengesahan bayaran dan sokongan, dengan akses kepada pihak perlu sahaja. Maklumat sulit tidak dijual atau didedah tanpa asas sah. Kelulusan pihak ketiga, gangguan, ranking carian dan hasil perniagaan tidak dijamin. Kenny Studio kekal bertanggungjawab bagi kerja dipersetujui dan bantuan munasabah; hak berkanun tidak dikecualikan.')),
(('Complaints, settlement & applicable rights','争议、结算与适用权利','Aduan, penyelesaian & hak terpakai'),
('Contact hello@kennystudio.cfd with the order number and issue. Both parties first seek a documented, reasonable resolution. Cancellation settlement lists completed work and approved non-recoverable costs; it does not automatically charge the entire unpaid project balance. The written quote governs project-specific details, subject to mandatory law. Malaysia law applies where applicable, without removing non-excludable consumer rights or access to a competent court or tribunal.','请联系 hello@kennystudio.cfd，注明订单号和问题。双方先以书面方式协商合理解决。取消结算须列明已完成工作及获同意且不可退的费用，不自动追收全部未付项目余额。项目细节按双方书面报价确认，并受强制法律约束；适用时依马来西亚法律处理，不剥夺不可排除的消费者权利及向有管辖权法院或机构寻求救济的权利。','Hubungi hello@kennystudio.cfd dengan nombor pesanan dan isu. Kedua-dua pihak mendapatkan penyelesaian munasabah bertulis dahulu. Penyelesaian pembatalan memperincikan kerja dan kos tidak boleh pulang yang diluluskan; baki projek tidak dicaj sepenuhnya secara automatik. Sebut harga bertulis mengawal butiran projek tertakluk undang-undang mandatori. Undang-undang Malaysia terpakai apabila berkenaan tanpa menghapuskan hak pengguna mandatori atau akses kepada mahkamah/tribunal berbidang kuasa.'))]
LANGS=('en','zh','ms')
def tr(value,lang):return value[LANGS.index(lang)]
def render_policy(prefix,lang,standalone=False):
 title=tr(('Project policy & mutual protection','项目政策与双方保障','Polisi projek & perlindungan bersama'),lang)
 intro=tr(('Clear commitments before work begins. Read these terms together with your written quotation.','开工前说明双方承诺，请与书面报价一并阅读。','Komitmen jelas sebelum kerja bermula. Baca bersama sebut harga bertulis.'),lang)
 highlight=tr(('After confirmed work starts, the 50% deposit is normally non-refundable if the client cancels, subject to reasonable settlement and mandatory refund rights.','确认并开工后，客户中途取消，50% 订金原则不退；实际保留以合理结算及依法享有的退款权利为限。','Selepas kerja disahkan bermula, deposit 50% lazimnya tidak dipulangkan jika pelanggan membatalkan, tertakluk penyelesaian munasabah dan hak bayaran balik mandatori.'),lang)
 out='<section class="service-section" id="project-policy"><span class="service-eyebrow">KENNY STUDIO / POLICY · '+VERSION+'</span><'+('h1' if standalone else 'h2')+'>'+E(title)+'</'+('h1' if standalone else 'h2')+'><p>'+E(intro)+'</p><aside class="service-note"><strong>'+E(highlight)+'</strong></aside>'
 for i,(heading,body) in enumerate(CLAUSES,1):out+='<details class="service-faq"'+(' open' if i==3 else '')+'><summary>'+str(i).zfill(2)+' / '+E(tr(heading,lang))+'</summary><p>'+E(tr(body,lang))+'</p></details>'
 out+='<p class="service-note">'+E(tr(('An enquiry form submission does not itself confirm a quotation or start paid work. The final scope and these terms must be agreed before the deposit and project start.','提交咨询表单本身不代表确认报价或开始付费制作；最终范围与本条款须在订金和开工前确认。','Penghantaran pertanyaan tidak mengesahkan sebut harga atau memulakan kerja berbayar. Skop akhir dan terma mesti dipersetujui sebelum deposit dan permulaan.'),lang))+'</p><a class="service-text-link" href="mailto:hello@kennystudio.cfd">hello@kennystudio.cfd ↗</a></section>'
 return out
